    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        assert groups == 1, "only groups=1 is supported by this PTX kernel"
        assert out_channels % 2 == 0, "this PTX kernel register-blocks pairs of output channels and requires an even out_channels"
        self.conv2d = nn.Conv2d(in_channels, out_channels, (kernel_size, kernel_size), stride=stride, padding=padding, dilation=dilation, groups=groups, bias=bias)
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        module = _get_ptx_module()

        x = x.contiguous()
        if x.dtype != torch.float32:
            x = x.float()
        weight = self.conv2d.weight.contiguous()
        if weight.dtype != torch.float32:
            weight = weight.float()

        N, IC, IH, IW = x.shape
        OC = self.conv2d.out_channels
        KH = self.kernel_size
        KW = self.kernel_size
        stride = self.stride
        padding = self.padding
        dilation = self.dilation
        block = (32, 8, 1)
        tile_w = (block[0] - 1) * stride + (KW - 1) * dilation + 1
        tile_h = (block[1] - 1) * stride + (KH - 1) * dilation + 1
        shared_mem_bytes = IC * KH * KW * 4 * 2 + tile_h * tile_w * 4

        OH = (IH + 2 * padding - dilation * (KH - 1) - 1) // stride + 1
        OW = (IW + 2 * padding - dilation * (KW - 1) - 1) // stride + 1

        output = torch.empty((N, OC, OH, OW), dtype=torch.float32, device=x.device)

        if self.conv2d.bias is not None:
            has_bias = 1
            bias_tensor = self.conv2d.bias.contiguous()
            if bias_tensor.dtype != torch.float32:
                bias_tensor = bias_tensor.float()
        else:
            has_bias = 0
            bias_tensor = torch.empty(1, dtype=torch.float32, device=x.device)

        grid = (
            (OW + block[0] - 1) // block[0],
            (OH + block[1] - 1) // block[1],
            N * (OC // 2),
        )

        module.launch(
            "conv2d_kernel",
            grid=grid,
            block=block,
            arguments=[
                x, weight, bias_tensor, output,
                i32(N), i32(IC), i32(IH), i32(IW),
                i32(OC), i32(OH), i32(OW),
                i32(KH), i32(KW),
                i32(stride), i32(padding), i32(dilation),
                i32(has_bias),
            ],
            shared_memory=shared_mem_bytes,
            stream=torch.cuda.current_stream(x.device),
        )

        return output

